 17	function formatDatePill(dateStr: string, s: Strings): string {
 18	  const timestamp = parseToTimestamp(`${dateStr}T00:00:00`);
 19	  const date = timestamp ? fromTimestamp(timestamp) : fromTimestamp(timeNow());
 20	  const mm = String(date.getMonth() + 1).padStart(2, '0');
 21	  const dd = String(date.getDate()).padStart(2, '0');
 22	  const dayNames = [s.day_sun, s.day_mon, s.day_tue, s.day_wed, s.day_thu, s.day_fri, s.day_sat];
 23	  return `${mm}${s.date_suffix_month}${dd}${s.date_suffix_day} ${dayNames[date.getDay()]}`;
 24	}
