 32	function getSeatPositionColumns(seatType: string): Set<string> | null {
 33	  if (!supportsPositionPick(seatType)) return null;
 34	  if (seatType.includes('商务')) return new Set(['A', 'C', 'F']);
 35	  if (seatType.includes('一等')) return new Set(['A', 'C', 'D', 'F']);
 36	  return new Set(['A', 'B', 'C', 'D', 'F']);
 37	}
 38	
 39	function retainCompatibleSeatPositions(
 40	  preferences: SeatPositionsByPassengerId,
 41	  seatType: string,
 42	): SeatPositionsByPassengerId {
 43	  const columns = getSeatPositionColumns(seatType);
 44	  if (!columns) return {};
 45	
 46	  return Object.fromEntries(
 47	    Object.entries(preferences).filter(([, position]) => {
 48	      const [rawRow, column] = position.split('-');
 49	      const row = Number.parseInt(rawRow ?? '', 10);
 50	      return Number.isInteger(row) && row >= 0 && !!column && columns.has(column);
 51	    }),
 52	  );
 53	}
