 55	function formatSeatPosition(position: string): string {
 56	  const [rawRow, column] = position.split('-');
 57	  const row = Number.parseInt(rawRow ?? '', 10);
 58	  return `${Number.isInteger(row) ? row + 1 : rawRow}排${column}座`;
 59	}
