import type { StringKey } from '../res/strings';
import type { SelectedTrainDraft } from '../types';
type Strings = Record<StringKey, string>;
type SeatPositionsByPassengerId = NonNullable<SelectedTrainDraft['seatPositionsByPassengerId']>;

function formatDatePill(dateStr: string, s: Strings): string {
  const timestamp = parseToTimestamp(`${dateStr}T00:00:00`);
  const date = timestamp ? fromTimestamp(timestamp) : fromTimestamp(timeNow());
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const dayNames = [s.day_sun, s.day_mon, s.day_tue, s.day_wed, s.day_thu, s.day_fri, s.day_sat];
  return `${mm}${s.date_suffix_month}${dd}${s.date_suffix_day} ${dayNames[date.getDay()]}`;
}

function seatCountLabel(count: number, s: Strings): string {
  if (count === -1) return s.seat_waitlist;
  if (count === 0) return s.seat_none;
  return s.seat_available_short;
}

function getSeatPositionColumns(seatType: string): Set<string> | null {
  if (!supportsPositionPick(seatType)) return null;
  if (seatType.includes('商务')) return new Set(['A', 'C', 'F']);
  if (seatType.includes('一等')) return new Set(['A', 'C', 'D', 'F']);
  return new Set(['A', 'B', 'C', 'D', 'F']);
}

function retainCompatibleSeatPositions(
  preferences: SeatPositionsByPassengerId,
  seatType: string,
): SeatPositionsByPassengerId {
  const columns = getSeatPositionColumns(seatType);
  if (!columns) return {};

  return Object.fromEntries(
    Object.entries(preferences).filter(([, position]) => {
      const [rawRow, column] = position.split('-');
      const row = Number.parseInt(rawRow ?? '', 10);
      return Number.isInteger(row) && row >= 0 && !!column && columns.has(column);
    }),
  );
}

function formatSeatPosition(position: string): string {
  const [rawRow, column] = position.split('-');
  const row = Number.parseInt(rawRow ?? '', 10);
  return `${Number.isInteger(row) ? row + 1 : rawRow}排${column}座`;
}

